package dev.raf.radar;
import android.content.*;import android.view.*;import android.widget.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;
public class PointHistoryUiTest {
 View text(View v,String value){if(v instanceof TextView&&value.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=text(((ViewGroup)v).getChildAt(i),value);if(found!=null)return found;}return null;}
 Point point(){Point p=new Point("history-fixture","Родник",55.178,61.308,false);p.address="Труда, 203 · Челябинск";return p;}
 void setup()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Store s=new Store(c);s.prefs.edit().clear().putBoolean("autoUpdate",false).putBoolean("sounds",false).putBoolean("lineageSounds",false).putBoolean("experimentalStatistics",true).commit();AccountClient.save(s,new JSONObject().put("user",new JSONObject().put("id",999).put("name","Fixture")).put("session","a".repeat(64)));s.update(point());java.io.File dir=new java.io.File(c.getFilesDir(),"point-history-cache");java.io.File[] files=dir.listFiles();if(files!=null)for(java.io.File f:files)f.delete();ScreenTest.grantAccess();AccountClient.transport=(b,t)->new JSONObject().put("friends",new JSONArray());Statistics.transport=(b,t)->{JSONArray accepted=new JSONArray(),meta=b.optJSONArray("sources"),ack=new JSONArray();if(meta!=null)for(int i=0;i<meta.length();i++)ack.put(new JSONObject().put("sourcePoint",meta.getJSONObject(i).getString("sourcePoint")).put("revision",meta.getJSONObject(i).getLong("revision")));return new JSONObject().put("accepted",accepted).put("acceptedSources",ack);};}
 @After public void cleanup(){AccountClient.transport=AccountClient::request;Statistics.transport=Statistics::request;PointStatistics.transport=PointStatistics::request;}
 @Test public void compactEditorBothThemesAndDraftCancelSave()throws Exception{setup();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
  AtomicReference<PointEditor> holder=new AtomicReference<>();for(String theme:new String[]{Appearance.STANDARD,Appearance.LINEAGE}){scenario.onActivity(a->{a.selectTheme(theme);PointEditor e=new PointEditor(a,point());holder.set(e);e.show();assertNotNull(text(e.dialog.getWindow().getDecorView(),"Сохранить"));assertEquals(View.GONE,e.controls.getVisibility());});ScreenTest.capture("point-editor-"+theme);scenario.onActivity(a->{PointEditor e=holder.get();e.name.setText("Не сохранять");e.draft.lat=56;text(e.dialog.getWindow().getDecorView(),"Отмена").performClick();Point saved=a.store.points().stream().filter(p->p.id.equals("history-fixture")).findFirst().get();assertEquals("Родник",saved.name);assertEquals(55.178,saved.lat,0);});}
  scenario.onActivity(a->{PointEditor e=new PointEditor(a,point());e.show();e.name.setText(" ");text(e.dialog.getWindow().getDecorView(),"Сохранить").performClick();assertTrue(e.dialog.isShowing());assertNotNull(e.name.getError());e.name.setText("Парковый");e.draft.lat=56;e.draft.address="Новое место";text(e.dialog.getWindow().getDecorView(),"Сохранить").performClick();Point saved=a.store.points().stream().filter(p->p.id.equals("history-fixture")).findFirst().get();assertEquals("Парковый",saved.name);assertEquals(56,saved.lat,0);assertFalse(e.dialog.isShowing());});}}
 String parameter(String q,String key)throws Exception{for(String part:q.split("&"))if(part.startsWith(key+"="))return java.net.URLDecoder.decode(part.substring(key.length()+1),"UTF-8");return "";}
 JSONObject fixture(boolean empty,String query)throws Exception{String date=parameter(query,"date"),timezone=parameter(query,"timezone");JSONArray slots=new JSONArray();java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US);f.setTimeZone(java.util.TimeZone.getTimeZone(timezone));long start=f.parse(date).getTime();for(int h=0;h<24;h++){JSONArray bins=new JSONArray();for(int i=0;i<12;i++){long at=start+h*3600000L+i*300000L;bins.put(new JSONObject().put("minute",i*5).put("count",empty?0:1).put("value",empty?JSONObject.NULL:i*10).put("max",empty?JSONObject.NULL:i*10).put("min",empty?JSONObject.NULL:i*10).put("lastAt",at).put("lastValue",i*10).put("peakAt",at));}slots.put(new JSONObject().put("hour",h).put("actual",empty?JSONObject.NULL:55).put("minimum",empty?JSONObject.NULL:0).put("maximum",empty?JSONObject.NULL:110).put("peakAt",empty?JSONObject.NULL:start+h*3600000L+55*60000).put("filled",empty?0:12).put("bins",bins).put("historical",empty?JSONObject.NULL:100+h*5).put("historyDays",empty?0:4));}return new JSONObject().put("schema",2).put("date",date).put("slots",slots).put("dayMax",110).put("historyDays",empty?0:4).put("timezone",timezone).put("generatedAt",System.currentTimeMillis());}
 @Test public void pointCardHasStatisticsAndHourlyHistoryUsesBothThemes()throws Exception{setup();PointStatistics.transport=(q,t)->fixture(false,q);try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){for(String theme:new String[]{Appearance.STANDARD,Appearance.LINEAGE}){scenario.onActivity(a->{a.selectTheme(theme);a.edit(point());assertNotNull(text(a.pointSheet,"Статистика"));text(a.pointSheet,"Статистика").performClick();});ScreenTest.capture("point-history-"+theme);androidx.test.espresso.Espresso.onView(androidx.test.espresso.matcher.ViewMatchers.withText(org.hamcrest.Matchers.containsString("История: 4 дня"))).check(androidx.test.espresso.assertion.ViewAssertions.matches(androidx.test.espresso.matcher.ViewMatchers.isDisplayed()));androidx.test.espresso.Espresso.onView(androidx.test.espresso.matcher.ViewMatchers.withContentDescription("Закрыть статистику точки")).perform(androidx.test.espresso.action.ViewActions.click());}}}
 @Test public void emptyAndFailedHistoryAreExplicitAndRetryWorks()throws Exception{setup();AtomicReference<PointStatistics> holder=new AtomicReference<>();PointStatistics.transport=(q,t)->{throw new java.io.IOException("fixture");};try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){scenario.onActivity(a->{PointStatistics p=new PointStatistics(a,point());holder.set(p);p.show();});ScreenTest.capture("point-history-error");scenario.onActivity(a->assertTrue(holder.get().status.getText().toString().contains("Не удалось")));PointStatistics.transport=(q,t)->fixture(true,q);scenario.onActivity(a->holder.get().retry.performClick());ScreenTest.capture("point-history-empty");JSONObject zero=new JSONObject().put("actual",0);scenario.onActivity(a->{assertTrue(holder.get().status.getText().toString().contains("пока нет"));assertEquals("0 ₽",PointStatistics.value(zero,"actual"));assertEquals("—",PointStatistics.value(new JSONObject(),"actual"));holder.get().dialog.dismiss();});}}
 @Test public void dayNavigationFocusAndOfflineCopy()throws Exception{setup();PointStatistics.transport=(q,t)->fixture(false,q);AtomicReference<PointStatistics> holder=new AtomicReference<>();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){scenario.onActivity(a->{PointStatistics p=new PointStatistics(a,point());holder.set(p);p.show();});ScreenTest.capture("point-day-focus");scenario.onActivity(a->{PointStatistics p=holder.get();assertNotNull(p.data);assertTrue(p.today());int hour=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);assertTrue(p.hours[hour].getBottom()>p.scroll.getScrollY());assertTrue(p.hours[hour].getTop()<p.scroll.getScrollY()+p.scroll.getHeight());assertFalse(p.next.isEnabled());});androidx.test.espresso.Espresso.onView(androidx.test.espresso.matcher.ViewMatchers.isAssignableFrom(PointStatistics.DayScroll.class)).perform(androidx.test.espresso.action.ViewActions.swipeLeft());ScreenTest.capture("point-previous-day");scenario.onActivity(a->{PointStatistics p=holder.get();assertFalse(p.today());assertEquals(p.key(),p.data.optString("date"));assertTrue(p.next.isEnabled());});androidx.test.espresso.Espresso.onView(androidx.test.espresso.matcher.ViewMatchers.isAssignableFrom(PointStatistics.DayScroll.class)).perform(androidx.test.espresso.action.ViewActions.swipeRight());ScreenTest.capture("point-day-return-today");scenario.onActivity(a->assertTrue(holder.get().today()));final int[] position={0};scenario.onActivity(a->{PointStatistics p=holder.get();p.scroll.scrollTo(0,p.hours[5].getTop());position[0]=p.scroll.getScrollY();p.retry.performClick();});ScreenTest.capture("point-day-refresh-position");scenario.onActivity(a->{assertTrue(Math.abs(holder.get().scroll.getScrollY()-position[0])<=a.dp(2));holder.get().dialog.dismiss();});PointStatistics.transport=(q,t)->{throw new java.io.IOException("offline fixture");};scenario.onActivity(a->{PointStatistics p=new PointStatistics(a,point());holder.set(p);p.show();});ScreenTest.capture("point-day-offline");scenario.onActivity(a->{assertNotNull(holder.get().data);assertTrue(holder.get().status.getText().toString().contains("Сохранённые данные"));holder.get().dialog.dismiss();});}}
}
